CREATE COLUMN TABLE "TEST_AP"."UIVK" ("TransSeq" INTEGER CS_INT NOT NULL , "LayerID" INTEGER CS_INT NOT NULL , "RootID" INTEGER CS_INT, "TransNum" INTEGER CS_INT, "Instance" INTEGER CS_INT DEFAULT 0, "INMTransSe" INTEGER CS_INT NOT NULL , PRIMARY KEY ("INMTransSe")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "UIVK_TRANSSEQ" ON "TEST_AP"."UIVK" ( "TransSeq" ASC, "LayerID" ASC )